# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import absence_notice

STUDENT = Student("1", "Doe", "Ann", "A")


def mark(day, status="absent", student_id="1"):
    return Mark(student_id, date(2026, 9, day), status)


class NoticeTests(unittest.TestCase):
    def test_lists_sorted_absences(self):
        marks = [mark(4), mark(2), mark(3, "present")]
        text = absence_notice(STUDENT, marks)
        self.assertEqual(
            text,
            "Ann Doe missed 2 day(s): 2026-09-02, 2026-09-04."
        )

    def test_other_student(self):
        marks = [mark(2), mark(3, student_id="2")]
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, marks)

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(2, "late")])
